{"code":"import pandas as pd, statsmodels.formula.api as smf
D=pd.read_csv('data/explore.csv'); candidates=['anneal_temp','cool_rate','carbon_pct','chromium_pct','grain_size','humidity','press_time','nickel_pct','porosity','cure_hours']
for v in candidates:
 d=D[['tensile_mpa','lab',v]].dropna(); m=smf.ols(f'tensile_mpa ~ {v} + C(lab)',d).fit()
 print(v,round(m.params[v],3),round(m.pvalues[v],5),len(d))
print('\nexposure correlations'); print(D[candidates].corr().round(2).to_string())"}
